    const filters=[{id:'all',name:i18n.t('Все нейросети')},...catalogProviders.map((p,i)=>({id:String(i),name:p.name,color:providers[p.name]?.color}))];
    $('#catalog-filters').innerHTML=filters.map(f=>`<button type="button" class="catalog-filter" data-catalog-filter="${f.id}"${f.color?` style="--provider-color:${f.color}"`:''} aria-pressed="${selected===f.id}"><span ${f.id==='all'?'':'data-i18n-skip'}>${escape(f.name)}</span></button>`).join('');
