  for(const column of ['left','right']){
    $('#work-videos-'+column).innerHTML=source.videos.map((video,index)=>({video,index})).filter(({video,index})=>(video.column||(index<3?'left':'right'))===column).map(({video,index})=>playerMarkup(video,index)).join('');
  }
  const players=[...document.querySelectorAll('.imported-video-player')].map(element=>({element,video:element.querySelector('video'),button:element.querySelector('button'),positioned:false,interacted:false}));
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
