/* nav-visit-notices.js */
(() => {
 'use strict';
 const day=24*60*60*1000,views=['models','guide'];let timer=0,identity='',ready=false,memory={models:0,guide:0};
 const key=view=>'jailbrok.nav-visit.v1.'+encodeURIComponent(identity)+'.'+view;
 function lastVisit(view){try{const saved=Number(localStorage.getItem(key(view)));if(Number.isFinite(saved)&&saved>0&&saved<=Date.now()+60000)return saved;}catch{}return memory[view]||0;}
 function visit(view){if(!views.includes(view))return;const now=Date.now();memory[view]=now;try{localStorage.setItem(key(view),String(now));}catch{}}
 function refresh(){
  clearTimeout(timer);if(!ready)return;const now=Date.now(),current=document.body.dataset.screen;let next=Infinity;
  const descriptions={ru:'Раздел не посещали последние 24 часа',en:'Not visited in the last 24 hours',hi:'पिछले 24 घंटों में यह अनुभाग नहीं देखा गया'};
  for(const view of views){const seen=lastVisit(view),due=current!==view&&(!seen||now-seen>=day);for(const button of document.querySelectorAll('.reference-nav-link[data-view="'+view+'"]')){button.dataset.visitDue=String(due);if(due)button.setAttribute('aria-description',descriptions[window.LabI18n?.language]||window.LabI18n.t(descriptions.en));else button.removeAttribute('aria-description');}if(seen+day>now)next=Math.min(next,seen+day-now);}
  if(!document.hidden&&Number.isFinite(next))timer=setTimeout(refresh,Math.max(1000,Math.min(day,next+25)));
 }
 function syncIdentity(){if(!ready)return;const next=window.jailbrokAuth?.user?.id||'guest';if(identity!==next){identity=next;memory={models:0,guide:0};}visit(document.body.dataset.screen);refresh();}
 document.addEventListener('jailbrok:viewchange',()=>{if(ready){visit(document.body.dataset.screen);refresh();}});
 document.addEventListener('jailbrok:auth-change',syncIdentity);document.addEventListener('jailbrok:languagechange',refresh);
 document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(timer);else if(ready){visit(document.body.dataset.screen);refresh();}});
 window.addEventListener('focus',refresh);window.addEventListener('storage',event=>{if(ready&&views.some(view=>event.key===key(view)))refresh();});window.addEventListener('pagehide',()=>clearTimeout(timer));window.addEventListener('pageshow',refresh);
 const start=()=>{ready=true;syncIdentity();};Promise.resolve(window.jailbrokAuth?.ready).then(start,start);
})();

